        if (notationProviderName == np) {
            nameFig.setText(rendering);
            damage();
        }
    }

    public NotationSettings getNotationSettings(NotationProvider np) {
        if (notationProviderName == np) {
            return getNotationSettings();
        }
        return null;
    }

    public Object getOwner(NotationProvider np) {
        if (notationProviderName == np) {
            return getOwner();
        }
        return null;
    }
