                if (name != null) {
                    abstraction.setName(name);
                }
                abstraction.getSuppliers().add((NamedElement) supplier);
                abstraction.getClients().add((NamedElement) client);
                ((NamedElement) client).getNearestPackage()
                        .getPackagedElements().add(abstraction);
