	d.setProject(this);
        diagrams.add(d);

        d.addPropertyChangeListener("name", new NamePCL());
        setSaveEnabled(true);
        ProjectEvent event = new ProjectEvent(d);
        for (ProjectListener listener : projectListeners) {
            listener.diagramAdded(event);
        }

