        if (handle instanceof Argument
                && (value == null || value instanceof Expression)) {
            Argument arg = (Argument) handle;
            Expression oldExp = arg.getValue();
            if (!equal(oldExp,(Expression) value)) {
                arg.setValue((Expression) value);
